const R = { topics: T };
R.search = function (q, lang) {
  const norm = (x) => x.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/<[^>]+>/g, ' ');
  const words = norm(q).split(/[^a-z0-9$]+/).filter(w => w.length > 1);
  if (!words.length) return [];
  return T.map(t => {
    const title = norm(t.title[lang]), body = norm(t.body[lang]), kw = norm(t.kw);
    let sc = 0; words.forEach(w => { const stem = w.length > 4 ? w.slice(0, -1) : w; if (title.includes(stem)) sc += 5; if (kw.includes(stem)) sc += 3; const m = body.split(stem).length - 1; sc += Math.min(m, 4); });
    return { t, sc };
  }).filter(x => x.sc > 0).sort((a, b) => b.sc - a.sc).slice(0, 6).map(x => x.t);
};
if (typeof module !== 'undefined' && module.exports) module.exports = R; else root.HeistRules = R;
